// TH16 v1.00a approved aliases of identical TH18 type slots (transcribe/th16/touhou-bullets.ecl).
const TH16_TALISMAN: int = 528;   // source type 11, color 4
const TH16_BIG_BALL: int = 640;   // source type 18, color 5

// th16_s4_mb1 — TH16 v1.00a Stage 4 midboss MBoss1 (st04mbs.ecl.txt:40-211).
// Source clock: MBoss:11 timerReset -> slot1 interrupt 1800 frames (MBoss:23);
// MBoss:26-28 move (-192,-64) -> (0,128) over 140 and wait; MBoss1:46 waits 120 more.

const TIME_LIMIT: int = 1924;   // 120 shell buffer + 1800 source window + 4 slack
const OPENING_BUFFER: int = 120;

// Emitter 0 EX chain (MBoss1_at:101-105 / MBoss1_at1B:155-159):
//   STEP a=60 b=1 c=0 d=0 r=+30deg, then a=60 r=-60deg, a=50 r=+90deg, a=40 r=-120deg,
//   s sentinel (-999999) = keep the entered logical speed v.
// Verified STEP branch: per-frame displacement v*(1-t/a); at the segment boundary the saved
// speed v is restored and the angle offset is added. Written as constant decel -v/a plus a
// boundary restore of v; the extra +v/a on the boundary frame cancels that frame's accel step,
// so every segment's first frame still moves at full v (probe: 3.00 -> 5.95 -> ... -> 91.52,
// then +3 on the boundary frame in the new direction).
xformdef MB_STEP(v: fx) {
    set_speed(at_effect(v + v/60fx));            // segment 1 (60f) starts at v
    @60 set_accel(at_effect(0fx - v/60fx));
    set_speed(at_effect(v + v/60fx));            // boundary: restore v
    turn(30deg);
    @60 set_accel(at_effect(0fx - v/60fx));      // segment 2 (60f)
    set_speed(at_effect(v + v/50fx));            // boundary: restore v
    turn(-60deg);
    @50 set_accel(at_effect(0fx - v/50fx));      // segment 3 (50f)
    set_speed(at_effect(v + v/40fx));            // boundary: restore v
    turn(90deg);
    @40 set_accel(at_effect(0fx - v/40fx));      // segment 4 (40f)
    set_speed(at_effect(v));                     // final boundary: restore v
    turn(-120deg);
    set_accel(0fx);
}

// --- moveRand(60,4,1.0) with moveLimit(0,128,280,64): same recipe as the verified TH18
// BossCard1/BossCard2 sample, adapted to this card's limit (inner x +-70, clamp x +-140,
// y 96..160). int slot 0 = step count, fx slots 0/1 = logical unit vector.
sub arm_next_step() {
    var k: int = self_int(0)+1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60-k) as fx / 60; }
    var nx: fx = $self_x+self_fx(0)*speed;
    var ny: fx = $self_y+self_fx(1)*speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx-$self_x, ny-$self_y, EASE_LINEAR);
}
sub begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    arm_next_step();
}
sub move_rand() {
    // Source 405b90: signed unit random * pi; values below are unwrapped BAM ints.
    var r: int = rand(65536)-32768;
    var a: int = r/3;
    if $self_x < -70fx {
        a = r/3;
    } else if $self_x > 70fx {
        a = r/3+32768;
        if a > 32768 { a = a-65536; }
    } else {
        a = r/4;
        var choose: int = rand(65536)%3;
        if $player_x > $self_x {
            if choose == 0 { a = a+32768; }
        } else {
            if choose != 0 { a = a+32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    begin_angle(a as angle);
}
sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        arm_next_step();
    }
}

// MBoss1_at / MBoss1_at1B: fixed-direction ring (aim 3), delta=0.
// counts 13(E)/29(N/H/L), layers 1(E/N)/2(H/L); layer speeds: E 1.5; N 2.0;
// H/L q0 3.2, q1 2.0. Spawn offset: etDist 20 then ANIM keeps position -= 4*velocity.
sub talisman_ring(start: angle, step: angle) {
    var rank: int = global(GVAR_RANK);
    var n: int = 29;
    var v0: fx = 3.2fx;
    if rank == RANK_EASY {
        n = 13;
        v0 = 1.5fx;
    } else if rank == RANK_NORMAL {
        v0 = 2fx;
    }
    var ang: angle = start;
    for w in 0..10 {
        sh_reset(0);
        sh_sprite(0, TH16_TALISMAN, 4);
        sh_ring(0, 1);
        sh_aim(0, 0);
        sh_count(0, n, 1);
        sh_angle(0, ang, 0deg);
        sh_speed(0, v0, 0fx);
        sh_dist(0, 20fx - 4fx*v0);
        sh_xform(0, MB_STEP(v0));
        sh_fire(0);
        if rank >= RANK_HARD {
            // native order is layer outer: q=0 (3.2) entire ring, then q=1 (2.0)
            sh_speed(0, 2fx, 0fx);
            sh_dist(0, 20fx - 8fx);
            sh_xform(0, MB_STEP(2fx));
            sh_fire(0);
        }
        ang = ang + step;
        card_wait(20);
    }
}

// MBoss1_at2: aimed ring (aim 2), count 20(E/N/H)/30(L), 1 layer,
// speed 1.5(E)/2.6(N)/3.5(H)/4.5(L); 4 waves 25 frames apart.
// Source etDist call targets emitter 0, so emitter 1 spawns at the owner point; the ANIM
// birth shift -4*velocity still applies.
sub big_ring() {
    var rank: int = global(GVAR_RANK);
    var n: int = 20;
    var v: fx = 3.5fx;
    if rank == RANK_EASY {
        v = 1.5fx;
    } else if rank == RANK_NORMAL {
        v = 2.6fx;
    } else if rank == RANK_LUNATIC {
        n = 30;
        v = 4.5fx;
    }
    for w in 0..4 {
        sh_reset(1);
        sh_sprite(1, TH16_BIG_BALL, 5);
        sh_ring(1, 1);
        sh_aim(1, 1);
        sh_count(1, n, 1);
        sh_angle(1, 90deg, 0deg);
        sh_speed(1, v, 0fx);
        sh_dist(1, 0fx - 4fx*v);
        sh_fire(1);
        card_wait(25);
    }
}

async sub mboss_body() {
    set_invuln(65535);
    set_hitbox(20fx);    // MBoss:20 setHitbox(40,40) -> circle radius 20
    set_hurtbox(24fx);   // MBoss:19 setHurtbox(48,48) -> circle radius 24
    set_self_int(3, 0);  // MBoss1:45 $I3 = 0 (no reader inside this card)

    // st04:1903 creates MBoss at (192,-32); MBoss:26 movePos(-192,-64) rewrites the ABS
    // position in the same entry frame, so the card starts from the post-movePos point.
    move_to(140, 0fx, 128fx, EASE_QUAD_OUT);   // MBoss:27 movePosTime(140, mode4, 0,128)
    wait(140);                                 // MBoss:28
    // MBoss1:42 moveLimit(0,128,280,64) is applied per step inside arm_next_step.
    wait(120);                                 // MBoss1:46

    talisman_ring(90deg, -2deg);   // MBoss1_at   : source 260..460
    card_wait(20);                 // MBoss1:52
    big_ring();                    // MBoss1_at2  : 480..580
    move_rand();                   // MBoss1:54 moveRand(60,4,1.0)
    card_wait(70);                 // MBoss1:55
    talisman_ring(90deg, 2deg);    // MBoss1_at1B : 650..850
    card_wait(20);                 // MBoss1:57
    big_ring();                    //             870..970
    move_rand();
    card_wait(70);                 //             970..1040

    talisman_ring(90deg, -2deg);   // second pass: 1040..1240
    card_wait(20);
    big_ring();                    //             1260..1360
    move_rand();
    card_wait(70);                 //             1360..1430
    talisman_ring(90deg, 2deg);    //             1430..1630
    card_wait(20);
    big_ring();                    //             1650..1750
    move_rand();
    card_wait(50);                 // timer at source 1800 cuts the remaining 20 of wait(70)
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(-192fx, -64fx, 15000, 0, 0, 0, mboss_body);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
